public class Main {
    static int[] getOrder(int[][] tasks) {
        int n = tasks.length;
        boolean[] done = new boolean[n];
        long time = 0;
        int[] result = new int[n];
        for (int step = 0; step < n; step++) {
            int best = -1;
            for (int i = 0; i < n; i++) {                   // scan every remaining task
                if (done[i] || tasks[i][0] > time) continue;
                if (best == -1 || tasks[i][1] < tasks[best][1] ||
                    (tasks[i][1] == tasks[best][1] && i < best)) best = i;
            }
            if (best == -1) {
                long next = Long.MAX_VALUE;
                for (int i = 0; i < n; i++) if (!done[i]) next = Math.min(next, tasks[i][0]);
                time = next;
                step--;
                continue;
            }
            done[best] = true;
            time += tasks[best][1];
            result[step] = best;
        }
        return result;
    }
}

