import java.util.*;

public class Main {
    static int[] getOrder(int[][] tasks) {
        int n = tasks.length;
        Integer[] indexed = new Integer[n];
        for (int i = 0; i < n; i++) indexed[i] = i;
        Arrays.sort(indexed, (a, b) -> tasks[a][0] - tasks[b][0]);   // sort by enqueue time, once

        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int[] result = new int[n];
        long time = 0;
        int ptr = 0, filled = 0;
        while (filled < n) {
            while (ptr < n && tasks[indexed[ptr]][0] <= time) {
                int i = indexed[ptr];
                heap.offer(new int[]{tasks[i][1], i});                  // newly available task
                ptr++;
            }
            if (heap.isEmpty()) {
                time = tasks[indexed[ptr]][0];                            // jump to the next enqueue time
                continue;
            }
            int[] top = heap.poll();
            time += top[0];
            result[filled++] = top[1];
        }
        return result;
    }
}

