#include <bits/stdc++.h>
using namespace std;

vector<int> getOrder(vector<vector<int>>& tasks) {
    int n = tasks.size();
    vector<int> indexed(n);
    iota(indexed.begin(), indexed.end(), 0);
    sort(indexed.begin(), indexed.end(), [&](int a, int b) { return tasks[a][0] < tasks[b][0]; });  // sort once

    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> heap;
    vector<int> result;
    long long time = 0;
    int ptr = 0;
    while ((int)result.size() < n) {
        while (ptr < n && tasks[indexed[ptr]][0] <= time) {
            int i = indexed[ptr];
            heap.push({tasks[i][1], i});                     // newly available task
            ptr++;
        }
        if (heap.empty()) {
            time = tasks[indexed[ptr]][0];                       // jump to the next enqueue time
            continue;
        }
        auto [procTime, i] = heap.top(); heap.pop();
        time += procTime;
        result.push_back(i);
    }
    return result;
}
